import type { Metadata } from 'next';
import Link from 'next/link';
import InteractiveFilters from '@/components/InteractiveFilters';
import ProductCard from '@/components/ProductCard';
import HomeHeader from '@/components/HomeHeader';
import { ChevronLeftIcon, ChevronRightIcon } from '@heroicons/react/24/solid';
import sql from '@/lib/db';
import { Product, Category } from '@/lib/types';

export const revalidate = 600;

type SearchParams = Promise<{ [key: string]: string | undefined }>;
type Row = Record<string, unknown>;

// ─── Метаданные ───────────────────────────────────────────────────────────────
export async function generateMetadata({
  searchParams,
  }: {
    searchParams: SearchParams;
    }): Promise<Metadata> {
      const params      = await searchParams;
        const category    = params.category;
          const subcategory = params.subcategory;
            const page        = parseInt(params.page || '1', 10);
              const pageStr     = page > 1 ? ` — страница ${page}` : '';

                const canonicalParams = new URLSearchParams();
                  if (category && category !== 'all') canonicalParams.set('category', category);
                    if (subcategory && subcategory !== 'all') canonicalParams.set('subcategory', subcategory);
                      const canonicalQuery = canonicalParams.toString();
                        const canonical = `https://bazariara.ge/${canonicalQuery ? '?' + canonicalQuery : ''}`;

                          if (!category || category === 'all') {
                              return {
                                    title: `BAZARI ARA: Товары для дома, сада, туризма и отдыха в Тбилиси${pageStr}`,
                                          description: 'Товары для дома, сада, туризма и детей в Тбилиси. Доставка за 2 часа по городу. Более 1000 товаров по доступным ценам — заказывайте онлайн!',
                                                alternates: { canonical },
                                                    };
                                                      }

                                                        let catName = category;
                                                          try {
                                                              const rows = await sql`
                                                                    SELECT DISTINCT category FROM products
                                                                          WHERE source = 'gorgia'
                                                                                  AND SPLIT_PART(external_id, '_', 1) = ${category}
                                                                                        LIMIT 1
                                                                                            `;
                                                                                                if (rows[0]?.category) catName = rows[0].category as string;
                                                                                                  } catch {}

                                                                                                    if (subcategory && subcategory !== 'all') {
                                                                                                        const subName = subcategory.split('-').map((w: string) => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
                                                                                                            return {
                                                                                                                  title: `${subName} — ${catName} | купить в Тбилиси | BAZARI ARA${pageStr}`,
                                                                                                                        description: `${subName} в категории «${catName}». Быстрая доставка по Тбилиси за 2 часа.`,
                                                                                                                              alternates: { canonical },
                                                                                                                                  };
                                                                                                                                    }

                                                                                                                                      return {
                                                                                                                                          title: `${catName} — купить в Тбилиси с доставкой за 2 часа | BAZARI ARA${pageStr}`,
                                                                                                                                              description: `Большой выбор товаров «${catName}» в Тбилиси. Заказывайте онлайн — доставим за 2 часа.`,
                                                                                                                                                  alternates: { canonical },
                                                                                                                                                    };
                                                                                                                                                    }

                                                                                                                                                    // ─── Страница ─────────────────────────────────────────────────────────────────
                                                                                                                                                    export default async function HomePage({
                                                                                                                                                      searchParams,
                                                                                                                                                      }: {
                                                                                                                                                        searchParams: SearchParams;
                                                                                                                                                        }) {
                                                                                                                                                          // Next.js 15: searchParams нужно await
                                                                                                                                                            const params = await searchParams;

                                                                                                                                                              const selectedCategory    = params.category || 'all';
                                                                                                                                                                const selectedSubCategory = params.subcategory || 'all';
                                                                                                                                                                  const searchQuery         = params.search || '';
                                                                                                                                                                    const currentPage         = parseInt(params.page || '1', 10);
                                                                                                                                                                      const ITEMS_PER_PAGE      = 20;
                                                                                                                                                                        const offset              = (currentPage - 1) * ITEMS_PER_PAGE;

                                                                                                                                                                          let products: Product[]        = [];
                                                                                                                                                                            let total                      = 0;
                                                                                                                                                                              let categoriesList: Category[] = [];
                                                                                                                                                                                let subCategoriesList: Category[] = [];

                                                                                                                                                                                  try {
                                                                                                                                                                                      // ── Категории — фикс GROUP BY: используем алиасы ──────────────────────
                                                                                                                                                                                          const catRows = await sql`
                                                                                                                                                                                                SELECT
                                                                                                                                                                                                        SPLIT_PART(external_id, '_', 1) AS key,
                                                                                                                                                                                                                MAX(category)     AS name,
                                                                                                                                                                                                                        MAX(category_en)  AS name_en,
                                                                                                                                                                                                                                MIN(image_url)    AS image_url
                                                                                                                                                                                                                                      FROM products
                                                                                                                                                                                                                                            WHERE source = 'gorgia'
                                                                                                                                                                                                                                                    AND image_url IS NOT NULL
                                                                                                                                                                                                                                                            AND category IS NOT NULL
                                                                                                                                                                                                                                                                  GROUP BY SPLIT_PART(external_id, '_', 1)
                                                                                                                                                                                                                                                                        ORDER BY MAX(category)
                                                                                                                                                                                                                                                                            `;
                                                                                                                                                                                                                                                                                categoriesList = (catRows as Row[]).map((r) => ({
                                                                                                                                                                                                                                                                                      key:      r.key as string,
                                                                                                                                                                                                                                                                                            name:     r.name as string,
                                                                                                                                                                                                                                                                                                  name_en:  (r.name_en as string) || null,
                                                                                                                                                                                                                                                                                                        imageUrl: (r.image_url as string) ?? '',
                                                                                                                                                                                                                                                                                                            }));

                                                                                                                                                                                                                                                                                                                // ── Подкатегории ───────────────────────────────────────────────────────
                                                                                                                                                                                                                                                                                                                    if (selectedCategory !== 'all') {
                                                                                                                                                                                                                                                                                                                          const subRows = await sql`
                                                                                                                                                                                                                                                                                                                                  SELECT
                                                                                                                                                                                                                                                                                                                                            LOWER(REPLACE(COALESCE(sub_category, ''), ' ', '-')) AS key,
                                                                                                                                                                                                                                                                                                                                                      MAX(sub_category)     AS name,
                                                                                                                                                                                                                                                                                                                                                                MAX(sub_category_en)  AS name_en,
                                                                                                                                                                                                                                                                                                                                                                          MIN(image_url)        AS image_url
                                                                                                                                                                                                                                                                                                                                                                                  FROM products
                                                                                                                                                                                                                                                                                                                                                                                          WHERE source = 'gorgia'
                                                                                                                                                                                                                                                                                                                                                                                                    AND image_url IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                              AND SPLIT_PART(external_id, '_', 1) = ${selectedCategory}
                                                                                                                                                                                                                                                                                                                                                                                                                        AND sub_category IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                GROUP BY LOWER(REPLACE(COALESCE(sub_category, ''), ' ', '-'))
                                                                                                                                                                                                                                                                                                                                                                                                                                        ORDER BY MAX(sub_category)
                                                                                                                                                                                                                                                                                                                                                                                                                                              `;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    subCategoriesList = (subRows as Row[]).map((r) => ({
                                                                                                                                                                                                                                                                                                                                                                                                                                                            key:      r.key as string,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    name:     r.name as string,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            name_en:  r.name_en as string ?? undefined,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    imageUrl: (r.image_url as string) ?? '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // ── Динамические фильтры ───────────────────────────────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const categoryFilter = selectedCategory !== 'all'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? sql`AND SPLIT_PART(external_id, '_', 1) = ${selectedCategory}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : sql``;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const subcategoryFilter = selectedSubCategory !== 'all'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? sql`AND LOWER(REPLACE(COALESCE(sub_category, ''), ' ', '-')) = ${selectedSubCategory.toLowerCase()}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : sql``;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const searchFilter = searchQuery.length >= 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ? sql`AND (name_ru ILIKE ${'%' + searchQuery + '%'} OR name ILIKE ${'%' + searchQuery + '%'})`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  : sql``;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const [countRows, productRows] = await Promise.all([
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            sql`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    SELECT COUNT(*) AS total
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FROM products
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHERE source = 'gorgia'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              AND image_url IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ${categoryFilter}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ${subcategoryFilter}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ${searchFilter}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  `,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sql`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                SELECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          id, external_id, source_url, gorgia_url,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    COALESCE(name_ru, name) AS name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              name_ru, name_en, name_ka,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        description_ru AS description,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  price, currency, in_stock, availability,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            category, category_en, sub_category, sub_category_en,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      image_url, images
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              FROM products
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      WHERE source = 'gorgia'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                AND image_url IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ${categoryFilter}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ${subcategoryFilter}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ${searchFilter}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ORDER BY in_stock DESC, updated_at DESC
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              LIMIT ${ITEMS_PER_PAGE} OFFSET ${offset}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            total    = parseInt(countRows[0].total as string);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                products = productRows as unknown as Product[];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.error('Neon fetch error:', error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const totalPages = Math.ceil(total / ITEMS_PER_PAGE);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const buildPageUrl = (pageNumber: number) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const p = new URLSearchParams();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (selectedCategory !== 'all')    p.set('category', selectedCategory);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (selectedSubCategory !== 'all') p.set('subcategory', selectedSubCategory);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (searchQuery)                   p.set('search', searchQuery);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p.set('page', pageNumber.toString());
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return `/?${p.toString()}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="bg-gray-900 min-h-screen text-white">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <main className="container mx-auto px-4 py-1 sm:px-6 lg:px-8">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <HomeHeader
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    categoryNames={selectedCategory !== 'all'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? (() => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const cat = categoriesList.find(c => c.key === selectedCategory);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return cat ? { ru: cat.name, en: cat.name_en } : undefined;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          : undefined}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <InteractiveFilters
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    categories={categoriesList}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              subCategories={subCategoriesList}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        selectedCategory={selectedCategory}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  selectedSubCategory={selectedSubCategory}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-8">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {products.map((product, index) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <ProductCard key={product.id} product={product} index={index} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </section>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {totalPages > 1 && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="mt-16 flex justify-center items-center gap-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {currentPage > 1 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Link href={buildPageUrl(currentPage - 1)} className="p-3 rounded-full bg-lime-500 text-gray-900 font-bold hover:bg-lime-400 transition-all shadow-lg hover:scale-105">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ChevronLeftIcon className="h-6 w-6" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="p-3 rounded-full bg-gray-700 opacity-50 cursor-not-allowed">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <ChevronLeftIcon className="h-6 w-6" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <span className="text-lg font-semibold text-white bg-gray-800/80 rounded-full px-5 py-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {currentPage} / {totalPages}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {currentPage < totalPages ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Link href={buildPageUrl(currentPage + 1)} className="p-3 rounded-full bg-lime-500 text-gray-900 font-bold hover:bg-lime-400 transition-all shadow-lg hover:scale-105">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <ChevronRightIcon className="h-6 w-6" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="p-3 rounded-full bg-gray-700 opacity-50 cursor-not-allowed">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <ChevronRightIcon className="h-6 w-6" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }